/**
 * OPTIONAL, LOCAL ONLY: build a "goku-classic" sprite pack from the 64px
 * frames in assets/goku/sprites/ (git-ignored third-party art).
 *
 * Output: packs/goku-classic/ (git-ignored). The app picks up packs/ on start
 * and uses the most recently built one unless settings name a pack.
 * The repository's default pack is generated by
 * scripts/generate-placeholder-sprites.ts and is never touched here.
 *
 * Usage: node scripts/build-sheets.js
 */

const fs = require("fs");
const path = require("path");
const { PNG } = require("pngjs");

const root = path.join(__dirname, "..");
const spriteDir = path.join(root, "assets", "goku", "sprites");
const outDir = path.join(root, "packs", "goku-classic");
const sheetDir = path.join(outDir, "sheets");

if (!fs.existsSync(spriteDir)) {
  console.error(`No frames found in ${path.relative(root, spriteDir)} - nothing to build.`);
  process.exit(1);
}

// sheet file -> ordered list of frames (from sprites/)
const SHEETS = {
  "idle.png": ["base_idle_0", "base_idle_1", "base_idle_2"],
  "fly.png": ["base_dash_0"],
  "drag.png": ["base_fall_0"],
  "punch_1.png": ["base_punch_0", "base_punch_1"],
  "punch_2.png": ["base_punch_2"],
  "punch_3.png": ["base_punch_3"],
  "kick_1.png": ["base_kick_0", "base_kick_1"],
  "kick_2.png": ["base_kick_2", "base_kick_3"],
  "block.png": ["base_block_0"],
  "kamehameha_charge.png": ["base_charge_0", "base_charge_1", "base_charge_2"],
  "kamehameha_fire.png": ["base_blast_0"],
  "kaioken.png": ["base_powerup_0", "base_powerup_1"],
  "laugh.png": ["base_victory_0"],
  "peek.png": ["base_land_0"],
  "train.png": ["base_punch_0", "base_punch_1", "base_punch_2", "base_punch_3"],
  "spar.png": ["base_kick_0", "base_kick_1", "base_kick_2", "base_kick_3"],
  "strikes.png": [
    "base_punch_0", "base_punch_1", "base_punch_2", "base_punch_3",
    "base_kick_0", "base_kick_1", "base_kick_2", "base_kick_3",
  ],
};

// action -> sheet (layout of the original manifest)
const ACTION_SHEETS = {
  "idle": "idle.png",
  "fly": "fly.png",
  "hover": "idle.png",
  "nimbus_ride": "idle.png",
  "punch_1": "punch_1.png",
  "punch_2": "punch_2.png",
  "punch_3": "punch_3.png",
  "kick_1": "kick_1.png",
  "kick_2": "kick_2.png",
  "uppercut": "punch_3.png",
  "block": "block.png",
  "kamehameha_charge": "kamehameha_charge.png",
  "kamehameha_fire": "kamehameha_fire.png",
  "kaioken": "kaioken.png",
  "laugh": "laugh.png",
  "scroll_unroll": "idle.png",
  "peek": "peek.png",
  "stretch": "laugh.png",
  "drink": "peek.png",
  "thinking": "idle.png",
  "done": "laugh.png",
  "drag": "drag.png",
  "sleep": "peek.png",
  "working": "idle.png",
  "confused": "peek.png",
  "eat": "peek.png",
  "train": "train.png",
  "scratch_head": "peek.png",
  "yawn": "peek.png",
  "stomach_growl": "peek.png",
  "look_around": "idle.png",
  "spar": "spar.png",
  "strikes": "strikes.png"
};
const FPS = { strikes: 12, punch_1: 12, punch_2: 12, punch_3: 12, uppercut: 12, kick_1: 12, kick_2: 12, spar: 12 };
const LOOP = new Set(["idle", "fly", "hover", "nimbus_ride", "kaioken", "thinking", "drag", "sleep", "working", "train"]);

fs.mkdirSync(sheetDir, { recursive: true });
const info = {};
for (const [file, names] of Object.entries(SHEETS)) {
  const frames = names.map((n) => PNG.sync.read(fs.readFileSync(path.join(spriteDir, `${n}.png`))));
  const fw = frames[0].width;
  const fh = frames[0].height;
  const sheet = new PNG({ width: fw * frames.length, height: fh });
  frames.forEach((f, i) => PNG.bitblt(f, sheet, 0, 0, fw, fh, i * fw, 0));
  fs.writeFileSync(path.join(sheetDir, file), PNG.sync.write(sheet));
  info[file] = { fw, fh, count: frames.length };
}

const actions = {};
for (const [name, file] of Object.entries(ACTION_SHEETS)) {
  const s = info[file];
  if (!s) continue;
  actions[name] = {
    sheet: `sheets/${file}`,
    frameWidth: s.fw,
    frameHeight: s.fh,
    frameCount: s.count,
    framesPerRow: s.count,
    fps: FPS[name] ?? 8,
    anchorX: Math.round(s.fw / 2),
    anchorY: Math.round(s.fh * 0.875),
    loop: LOOP.has(name),
    frameEvents: {},
    flip: false,
  };
}
fs.writeFileSync(path.join(outDir, "actions.json"), JSON.stringify({ actions }, null, 2) + "\n");
fs.writeFileSync(
  path.join(outDir, "pack.json"),
  JSON.stringify(
    { name: "Goku classic (local)", author: "local", version: "1.0.0", license: "Personal use only.", facing: "right", rendering: "pixelated" },
    null,
    2
  ) + "\n"
);
console.log(`Built ${Object.keys(actions).length} actions into ${path.relative(root, outDir)}`);
